export function Pagination({ page, totalPages, onChange }: { page: number; totalPages: number; onChange: (page: number) => void }) { if (totalPages <= 1) return null; return <div className="mt-5 flex items-center justify-between border-t border-[#ddd8ce] pt-4 text-xs font-medium text-[#8a8174]"><span>{page + 1} / {totalPages}</span><div className="flex gap-2"><button className="button button-secondary" disabled={page === 0} onClick={() => onChange(page - 1)}>Previous</button><button className="button button-secondary" disabled={page + 1 >= totalPages} onClick={() => onChange(page + 1)}>Next</button></div></div>; }
